<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { QuantityToggleContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: QuantityToggleContract  = $props();
const value=control(()=>p.value,untrack(()=>p.defaultValue),untrack(()=>p.min??0),value=>p.onValueChange?.({value}));let root:HTMLDivElement;const uid=$props.id();$effect(()=>{const min=p.min??0,max=p.max??10,step=p.step??1,levels=(max-min)/step;if(![min,max,step,value.value].every(Number.isFinite)||step<=0||!Number.isInteger(levels)||levels<1||levels>10||value.value<min||value.value>max||!Number.isInteger((value.value-min)/step))throw new RangeError('Quantity requires at most eleven consistent levels');});resetField(()=>root,()=>value.reset());
</script>
<div bind:this={root} role="group" aria-labelledby={p.id??uid} {...owned('quantity-toggle','root',p.disabled?'disabled':value.value===(p.min??0)?'at-minimum':value.value===(p.max??10)&&'at-maximum')}><span id={p.id??uid} {...owned('quantity-toggle','label')}>{p.label}</span><button type="button" {...owned('quantity-toggle','decrement')} aria-label={`${p.label} 줄이기`} disabled={p.disabled} aria-disabled={Boolean(p.disabled)||value.value<=(p.min??0)} onclick={event=>{event.currentTarget.focus();if(value.value>(p.min??0))value.request(value.value-(p.step??1));}}>−</button><output {...owned('quantity-toggle','output')} aria-live="polite">{value.value}{p.unit??''}</output><button type="button" {...owned('quantity-toggle','increment')} aria-label={`${p.label} 늘리기`} disabled={p.disabled} aria-disabled={Boolean(p.disabled)||value.value>=(p.max??10)} onclick={event=>{event.currentTarget.focus();if(value.value<(p.max??10))value.request(value.value+(p.step??1));}}>+</button>{#if p.name}<input {...owned('quantity-toggle','hidden-input')} type="hidden" name={p.name} value={value.value} disabled={p.disabled}/>{/if}</div>
